package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_rating_acknowledgment",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_ack_final",columnNames={"agency_id","final_rating_id"}))
public class PerformanceRatingAcknowledgment extends RspAuditedEntity{public enum Status{ACKNOWLEDGED,CLOSED_WITHOUT_ACKNOWLEDGMENT}@Column(name="final_rating_id",nullable=false,length=36)private String finalRatingId;@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private Status status;@Column(name="employee_response",length=2000)private String employeeResponse;@Column(name="closure_reason",length=2000)private String closureReason;@Column(name="acted_by",nullable=false,length=100)private String actedBy;@Column(name="acted_at",nullable=false)private Instant actedAt;protected PerformanceRatingAcknowledgment(){}public PerformanceRatingAcknowledgment(String a,String f,String c,String employee,String response,String actor,Instant at){super(a);finalRatingId=requiredText(f,"finalRatingId");ratingCaseId=requiredText(c,"ratingCaseId");employeeNo=requiredText(employee,"employeeNo");employeeResponse=optionalText(response);actedBy=requiredText(actor,"actor");actedAt=at;status=Status.ACKNOWLEDGED;}public static PerformanceRatingAcknowledgment close(String a,String f,String c,String employee,String reason,String actor,Instant at){PerformanceRatingAcknowledgment x=new PerformanceRatingAcknowledgment(a,f,c,employee,null,actor,at);x.status=Status.CLOSED_WITHOUT_ACKNOWLEDGMENT;x.closureReason=x.requiredText(reason,"reason");return x;}public String getFinalRatingId(){return finalRatingId;}public String getRatingCaseId(){return ratingCaseId;}public String getEmployeeNo(){return employeeNo;}public Status getStatus(){return status;}public String getEmployeeResponse(){return employeeResponse;}public String getClosureReason(){return closureReason;}public String getActedBy(){return actedBy;}public Instant getActedAt(){return actedAt;}}
